import json

if not _items:
    raise ValueError("Baserow returned no qualification-scoring prompt records.")


def fields_of(item):
    data = item.get("json", {})
    nested = data.get("fields")
    return nested if isinstance(nested, dict) else data


def get_value(fields, names):
    for name in names:
        if name in fields and fields[name] is not None:
            return fields[name]
    return None


def scalar(value):
    if isinstance(value, dict):
        for key in ("value", "name", "label"):
            nested = value.get(key)
            if nested is not None:
                return nested
        return value.get("id")

    if isinstance(value, list) and len(value) == 1:
        return scalar(value[0])

    return value


def is_enabled(value):
    value = scalar(value)

    if isinstance(value, bool):
        return value

    if isinstance(value, (int, float)):
        return value == 1

    if isinstance(value, str):
        return value.strip().lower() in ("true", "1", "yes", "enabled")

    return False


def normalize_output_structure(value, prompt_key):
    value = scalar(value)

    if isinstance(value, dict):
        schema = value
    elif isinstance(value, str) and value.strip():
        try:
            schema = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Prompt '{prompt_key}' has invalid JSON in Output Structure."
            ) from exc
    else:
        raise ValueError(
            f"Prompt '{prompt_key}' has no Output Structure JSON Schema."
        )

    if not isinstance(schema, dict):
        raise ValueError(
            f"Prompt '{prompt_key}' Output Structure must be a JSON object."
        )

    if schema.get("type") != "object":
        raise ValueError(
            f"Prompt '{prompt_key}' Output Structure must define an object schema."
        )

    return schema


def normalize_temperature(value, prompt_key):
    value = scalar(value)

    if value is None or (isinstance(value, str) and not value.strip()):
        raise ValueError(
            f"Prompt '{prompt_key}' is missing Temperature."
        )

    if isinstance(value, str):
        try:
            value = float(value)
        except ValueError as exc:
            raise ValueError(
                f"Prompt '{prompt_key}' has invalid Temperature."
            ) from exc

    return value


selected = []
for item in _items:
    fields = fields_of(item)
    prompt_key = scalar(
        get_value(
            fields,
            ["Prompt Key", "prompt_key", "Key", "key", "Name", "name"],
        )
    )

    if prompt_key != "qualification_scoring":
        continue

    active = get_value(fields, ["Active", "active", "Enabled", "enabled"])
    if active is not None and not is_enabled(active):
        continue

    template = scalar(
        get_value(
            fields,
            ["Prompt Template", "Prompt", "Template", "prompt_template"],
        )
    )
    output_structure = normalize_output_structure(
        get_value(
            fields,
            [
                "Output Structure",
                "output_structure",
                "Output Schema",
                "output_schema",
            ],
        ),
        prompt_key,
    )
    temperature = normalize_temperature(
        get_value(fields, ["Temperature", "temperature"]),
        prompt_key,
    )
    version = scalar(
        get_value(fields, ["Version", "Prompt Version", "version"])
    )

    if not isinstance(template, str) or not template.strip():
        raise ValueError("qualification_scoring prompt template is missing.")

    selected.append(
        {
            "qualification_scoring_prompt_key": prompt_key,
            "qualification_scoring_prompt_version": version,
            "qualification_scoring_temperature": temperature,
            "qualification_scoring_prompt_template": template,
            "qualification_scoring_output_structure": output_structure,
        }
    )

if not selected:
    raise ValueError(
        "No active qualification_scoring prompt record was found in Baserow."
    )

return [{"json": selected[0]}]

import json

if not _items:
    raise ValueError("Qualification scoring received no merged input.")

data = _items[0]["json"]
job_description = data.get("job_description")
master_cv = data.get("master_cv")
job_context = data.get("job_context")
template = data.get("qualification_scoring_prompt_template")

if not isinstance(job_description, str) or not job_description.strip():
    raise ValueError("job_description must be a non-empty string.")
if not isinstance(master_cv, dict):
    raise ValueError("master_cv must be an object.")
if not isinstance(job_context, dict):
    raise ValueError("job_context must be an object.")
if not isinstance(template, str) or not template.strip():
    raise ValueError("Qualification-scoring prompt template is missing.")

compact_cv = json.dumps(
    master_cv,
    ensure_ascii=False,
    separators=(",", ":"),
)

prompt = template
for placeholder, value in {
    "[[job_description]]": job_description.strip(),
    "[[master_cv_json]]": compact_cv,
    "[[master_cv]]": compact_cv,
}.items():
    prompt = prompt.replace(placeholder, value)

return [
    {
        "json": {
            **data,
            "qualification_scoring_prompt": prompt,
        }
    }
]

import json


def extract_parsed(root):
    output = root.get("output")

    if isinstance(output, dict):
        return output

    if isinstance(output, str):
        try:
            parsed = json.loads(output)
        except json.JSONDecodeError as exc:
            raise ValueError(
                "Qualification-scoring output was not valid JSON after parsing."
            ) from exc
        if isinstance(parsed, dict):
            return parsed

    try:
        value = root["response"]["generations"][0][0]["text"]
    except (KeyError, IndexError, TypeError):
        value = None

    if isinstance(value, dict):
        return value

    if isinstance(value, str):
        try:
            parsed = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(
                "Qualification-scoring output was not valid JSON after parsing."
            ) from exc
        if isinstance(parsed, dict):
            return parsed

    raise ValueError("Could not locate the parsed qualification-scoring output.")


if not _items:
    raise ValueError("The qualification-scoring model returned no items.")

parsed = extract_parsed(_items[0]["json"])

if not isinstance(parsed, dict):
    raise ValueError("The qualification-scoring output must be a JSON object.")

score = parsed.get("qualification_score")
should_apply = parsed.get("should_apply")

if not isinstance(score, int) or isinstance(score, bool):
    raise ValueError("qualification_score must be an integer.")

if score < 0 or score > 100:
    raise ValueError("qualification_score must be between 0 and 100.")

if not isinstance(should_apply, bool):
    raise ValueError("should_apply must be a boolean.")

normalized = {
    "qualification_score": score,
    "should_apply": should_apply,
}

return [
    {
        "json": {
            "qualification_scoring_response": json.dumps(
                normalized,
                ensure_ascii=False,
                separators=(",", ":"),
            )
        }
    }
]

import json

if not _items:
    raise ValueError("Qualification scoring received no final merged input.")

data = _items[0]["json"]
context = data.get("job_context")
if not isinstance(context, dict):
    raise ValueError("job_context must be an object.")

parsed = json.loads(data["qualification_scoring_response"])
score = parsed.get("qualification_score")
should_apply = parsed.get("should_apply")

if not isinstance(score, int) or isinstance(score, bool):
    raise ValueError("qualification_score must be an integer.")
if score < 0 or score > 100:
    raise ValueError("qualification_score must be between 0 and 100.")
if not isinstance(should_apply, bool):
    raise ValueError("should_apply must be a boolean.")

existing_prompt_usage = context.get("prompt_usage")
if not isinstance(existing_prompt_usage, dict):
    existing_prompt_usage = {}

prompt_usage = {
    **existing_prompt_usage,
    "qualification_scoring": {
        "prompt_key": data.get("qualification_scoring_prompt_key"),
        "version": data.get("qualification_scoring_prompt_version"),
        "temperature": data.get("qualification_scoring_temperature"),
    },
}

return [
    {
        "json": {
            **context,
            "master_cv": data.get("master_cv"),
            "qualification_scoring_json": parsed,
            "qualification_score": score,
            "should_apply": should_apply,
            "prompt_usage": prompt_usage,
        }
    }
]
